query businessPlatformCountAccountByPlan ( $accountId:ID! $businessPlatformCountAccountByPlanInput:BusinessPlatformCountAccountByPlanInput) {
	businessPlatform ( accountId:$accountId ) {
		countAccountByPlan ( input:$businessPlatformCountAccountByPlanInput  )  {
			items {
				plan
				count
			}
		}
	}	
}
